#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int maxProduct(int* nums, int numsSize) {
    int currentMax = nums[0], currentMin = nums[0], answer = nums[0];
    for (int i = 1; i < numsSize; ++i) {
        int x = nums[i];
        int a = x, b = currentMax * x, c = currentMin * x;
        currentMax = a;
        if (b > currentMax) currentMax = b;
        if (c > currentMax) currentMax = c;
        currentMin = a;
        if (b < currentMin) currentMin = b;
        if (c < currentMin) currentMin = c;
        if (currentMax > answer) answer = currentMax;
    }
    return answer;
}

