class Solution {
    public int maxProduct(int[] nums) {
        int currentMax = nums[0], currentMin = nums[0], answer = nums[0];
        for (int i = 1; i < nums.length; i++) {
            int x = nums[i];
            int a = x;
            int b = currentMax * x;
            int c = currentMin * x;
            currentMax = Math.max(a, Math.max(b, c));
            currentMin = Math.min(a, Math.min(b, c));
            answer = Math.max(answer, currentMax);
        }
        return answer;
    }
}

